  "design_rules": {
    "market_definition": "Market = 商业运营单元（销售区域），一个Market可包含多个国家（如EU Market包含FR/DE/IT/ES），也可只含一个国家（如US Market）",
    "market_country_unique": "market_country 表的 (market_id, country_id) 组合唯一，确保一个国家只能归属一个Market",
    "country_simplicity": "country 表只保留基础属性（名称、大洲、时区、电话区号、默认货币/语言），税费/合规/地址等业务配置由独立模块管理",
    "translation_strategy": "混合策略：核心内容（商品/类目）集中翻译，长尾内容（UGC）分布式翻译。source_hash 检测源内容变化，status=outdated 触发重译",
    "channel_granularity": "Channel 归属 Market，按策略划分（如 EU Market 的 Online/Retail 渠道），不按国家拆分",
    "cross_border_default": "Market 内跨境购买是默认能力（cross_border_enabled=true），无需额外配置",
    "domain_flexibility": "market_domain 支持统一域名（primary）或国家级独立域名（country_specific），通过 domain_type 区分",
    "exchange_rate_strategy": "market_currency 支持固定汇率（fixed）或动态汇率（dynamic），markup_percentage 用于加价策略",
    "exception_config": "market_country.custom_config 存储国家级例外配置（JSON），覆盖 Market 默认策略",
    "reference_data_pk": "基础参考数据（country/currency/language）使用国际标准代码作主键（ISO 3166-1/ISO 4217/ISO 639-1），语义清晰，跨模块引用时可读性强"
  }
